import{_ as a,c as o,o as r,ah as l}from"./chunks/framework.l36K22_3.js";const t="/assets/page0.B8sapXt_.png",m=JSON.parse('{"title":"浏览器跨域","description":"","frontmatter":{},"headers":[],"relativePath":"tiku/network/page0.md","filePath":"tiku/network/page0.md","lastUpdated":1731047437000}'),i={name:"tiku/network/page0.md"};function c(n,e,s,d,h,p){return r(),o("div",null,e[0]||(e[0]=[l('<h1 id="浏览器跨域" tabindex="-1">浏览器跨域 <a class="header-anchor" href="#浏览器跨域" aria-label="Permalink to &quot;浏览器跨域&quot;">​</a></h1><h2 id="相关问题" tabindex="-1">相关问题 <a class="header-anchor" href="#相关问题" aria-label="Permalink to &quot;相关问题&quot;">​</a></h2><ul><li>什么是跨域</li><li>为什么会跨域</li><li>为什么有跨域限制</li><li>怎么解决跨域</li></ul><h2 id="回答关键点" tabindex="-1">回答关键点 <a class="header-anchor" href="#回答关键点" aria-label="Permalink to &quot;回答关键点&quot;">​</a></h2><p><code>CORS</code> <code>同源策略</code></p><p>跨域问题的来源是浏览器为了请求安全而引入的基于同源策略的安全特性。当页面和请求的协议、主机名或端口不同时，浏览器判定两者不同源，即为跨域请求。需要注意的是跨域是浏览器的限制，服务端并不受此影响。当产生跨域时，我们可以通过 JSONP、CORS、postMessage 等方式解决。</p><h2 id="知识点深入" tabindex="-1">知识点深入 <a class="header-anchor" href="#知识点深入" aria-label="Permalink to &quot;知识点深入&quot;">​</a></h2><h3 id="_1-跨域问题的来源" tabindex="-1">1. 跨域问题的来源 <a class="header-anchor" href="#_1-跨域问题的来源" aria-label="Permalink to &quot;1. 跨域问题的来源&quot;">​</a></h3><p>跨域问题的来源是浏览器为了请求安全而引入的基于同源策略（Same-origin policy）的安全特性。同源策略是浏览器一个非常重要的安全策略，基于这个策略可以限制非同源的内容与当前页面进行交互，从而减少页面被攻击的可能性。</p><p>当页面和请求的协议、主机名或端口不同时，浏览器判定两者不同源，从而产生跨域。需要注意的是跨域是浏览器的限制，实际请求已经正常发出和响应了。</p><h3 id="_2-如何判定跨域" tabindex="-1">2. 如何判定跨域 <a class="header-anchor" href="#_2-如何判定跨域" aria-label="Permalink to &quot;2. 如何判定跨域&quot;">​</a></h3><p><img src="'+t+'" alt="" loading="lazy"></p><p>如上图所示，一个 origin 由协议（Protocol）、主机名（Host）和端口（Port）组成，这三块也是同源策略的判定条件，只有当协议、主机名和端口都相同时，浏览器才判定两者是同源关系，否则即为跨域。</p><h3 id="_3-跨域的解决方案" tabindex="-1">3. 跨域的解决方案 <a class="header-anchor" href="#_3-跨域的解决方案" aria-label="Permalink to &quot;3. 跨域的解决方案&quot;">​</a></h3><p>前端常见的跨域解决方案有 CORS、反向代理（Reverse Proxy）、JSONP 等。</p><h4 id="_3-1-cors-cross-origin-resource-sharing" tabindex="-1">3.1 CORS (Cross-Origin Resource Sharing) <a class="header-anchor" href="#_3-1-cors-cross-origin-resource-sharing" aria-label="Permalink to &quot;3.1 CORS (Cross-Origin Resource Sharing)&quot;">​</a></h4><p>CORS 是目前最为广泛的解决跨域问题的方案。方案依赖服务端/后端在响应头中添加 Access-Control-Allow-* 头，告知浏览器端通过此请求。</p><h5 id="涉及到的端" tabindex="-1">涉及到的端 <a class="header-anchor" href="#涉及到的端" aria-label="Permalink to &quot;涉及到的端&quot;">​</a></h5><p>CORS 只需要服务端/后端支持即可，不涉及前端改动。</p><h5 id="具体实现方式" tabindex="-1">具体实现方式 <a class="header-anchor" href="#具体实现方式" aria-label="Permalink to &quot;具体实现方式&quot;">​</a></h5><p>CORS 将请求分为简单请求（Simple Requests）和需预检请求（Preflighted requests），不同场景有不同的行为：</p><p><strong>简单请求</strong></p><p>不会触发预检请求的称为简单请求。当请求满足以下条件时就是一个简单请求：</p><ul><li>请求方法：GET、HEAD、POST。</li><li>请求头：<code>Accept</code>、<code>Accept-Language</code>、<code>Content-Language</code>、<code>Content-Type</code>。 <ul><li><code>Content-Type</code> 仅支持：<code>application/x-www-form-urlencoded</code>、<code>multipart/form-data</code>、<code>text/plain</code>。</li></ul></li></ul><p><strong>需预检请求</strong></p><p>当一个请求不满足以上简单请求的条件时，浏览器会自动向服务端发送一个 OPTIONS 请求，通过服务端返回的 <code>Access-Control-Allow-*</code> 判定请求是否被允许。</p><p>CORS 引入了以下几个以 <code>Access-Control-Allow-*</code> 开头：</p><ul><li><code>Access-Control-Allow-Origin</code> 表示允许的来源</li><li><code>Access-Control-Allow-Methods</code> 表示允许的请求方法</li><li><code>Access-Control-Allow-Headers</code> 表示允许的请求头</li><li><code>Access-Control-Allow-Credentials</code> 表示允许携带认证信息</li></ul><p>当请求符合响应头的这些条件时，浏览器才会发送并响应正式的请求。</p><h4 id="_3-2-反向代理" tabindex="-1">3.2 反向代理 <a class="header-anchor" href="#_3-2-反向代理" aria-label="Permalink to &quot;3.2 反向代理&quot;">​</a></h4><p>反向代理解决跨域问题的方案依赖同源的服务端对请求做一个转发处理，将请求从跨域请求转换成同源请求。</p><h5 id="涉及到的端-1" tabindex="-1">涉及到的端 <a class="header-anchor" href="#涉及到的端-1" aria-label="Permalink to &quot;涉及到的端&quot;">​</a></h5><p>反向代理只需要服务端/后端支持，几乎不涉及前端改动，只用切换接口即可。</p><h5 id="具体实现方式-1" tabindex="-1">具体实现方式 <a class="header-anchor" href="#具体实现方式-1" aria-label="Permalink to &quot;具体实现方式&quot;">​</a></h5><p>反向代理的实现方式为在页面同域下配置一套反向代理服务，页面请求同域的服务端，服务端请求上游的实际的服务端，之后将结果返回给前端。</p><h4 id="_3-3-jsonp" tabindex="-1">3.3 JSONP <a class="header-anchor" href="#_3-3-jsonp" aria-label="Permalink to &quot;3.3 JSONP&quot;">​</a></h4><p>JSONP 是一个相对古老的跨域解决方案，只支持 GET 请求。主要是利用了浏览器加载 JavaScript 资源文件时不受同源策略的限制而实现跨域获取数据。</p><h5 id="涉及到的端-2" tabindex="-1">涉及到的端 <a class="header-anchor" href="#涉及到的端-2" aria-label="Permalink to &quot;涉及到的端&quot;">​</a></h5><p>JSONP 需要服务端和前端配合实现。</p><h5 id="具体实现方式-2" tabindex="-1">具体实现方式 <a class="header-anchor" href="#具体实现方式-2" aria-label="Permalink to &quot;具体实现方式&quot;">​</a></h5><p>JSONP 的原理是利用了浏览器加载 JavaScript 资源文件时不受同源策略的限制而实现的。具体流程如下：</p><ol><li>全局注册一个函数，例如：window.getHZFEMember = (num) =&gt; console.log(&#39;HZFE Member: &#39; + num);。</li><li>构造一个请求 URL，例如：<a href="https://hzfe.org/api/hzfeMember?callback=getHZFEMember%E3%80%82" target="_blank" rel="noreferrer">https://hzfe.org/api/hzfeMember?callback=getHZFEMember。</a></li><li>生成一个 <code>&lt;script&gt;</code> 并把 src 设为上一步的请求 URL 并插入到文档中，如 <code>&lt;script src=&quot;https://hzfe.org/api/hzfeMember?callback=getHZFEMember&quot; /&gt;</code>。</li><li>服务端构造一个 JavaScript 函数调用表达式并返回，例如：getHZFEMember(17)。</li><li>浏览器加载并执行以上代码，输出 HZFE Member: 17。</li></ol><h5 id="非常用方式" tabindex="-1">非常用方式 <a class="header-anchor" href="#非常用方式" aria-label="Permalink to &quot;非常用方式&quot;">​</a></h5><ul><li>postMessage <ul><li>即在两个 origin 下分别部署一套页面 A 与 B，A 页面通过 iframe 加载 B 页面并监听消息，B 页面发送消息。</li></ul></li><li>window.name <ul><li>主要是利用 window.name 页面跳转不改变的特性实现跨域，即 iframe 加载一个跨域页面，设置 window.name，跳转到同域页面，可以通过 $(&#39;iframe&#39;).contentWindow.name 拿到跨域页面的数据。</li></ul></li><li>document.domain <ul><li>可将相同一级域名下的子域名页面的 document.domain 设置为一级域名实现跨域。</li><li>可将同域不同端口的 document.domain 设置为同域名实现跨域（端口被置为 null）。</li></ul></li></ul><h2 id="扩展阅读" tabindex="-1">扩展阅读 <a class="header-anchor" href="#扩展阅读" aria-label="Permalink to &quot;扩展阅读&quot;">​</a></h2><h3 id="_1-localstorage-sessionstorage-跨域" tabindex="-1">1. LocalStorage / SessionStorage 跨域 <a class="header-anchor" href="#_1-localstorage-sessionstorage-跨域" aria-label="Permalink to &quot;1. LocalStorage / SessionStorage 跨域&quot;">​</a></h3><p>LocalStorage 和 SessionStorage 同样受到同源策略的限制。而跨域读写的方式也可以使用前文提到的 postMessage。</p><h3 id="_2-跨域与监控" tabindex="-1">2. 跨域与监控 <a class="header-anchor" href="#_2-跨域与监控" aria-label="Permalink to &quot;2. 跨域与监控&quot;">​</a></h3><p>前端项目在统计前端报错监控时会遇到上报的内容只有 <code>Script Error</code> 的问题。这个问题也是由同源策略引起。在 <code>&lt;script&gt;</code> 标签上添加 <code>crossorigin=&quot;anonymous&quot;</code> 并且返回的 JS 文件响应头加上 <code>Access-Control-Allow-Origin: *</code> 即可捕捉到完整的错误堆栈。</p><h3 id="_3-跨域与图片" tabindex="-1">3. 跨域与图片 <a class="header-anchor" href="#_3-跨域与图片" aria-label="Permalink to &quot;3. 跨域与图片&quot;">​</a></h3><p>前端项目在图片处理时可能会遇到图片绘制到 Canvas 上之后却不能读取像素或导出 base64 的问题。这个问题也是由同源策略引起。解决方式和上文相同，给图片添加 <code>crossorigin=&quot;anonymous&quot;</code> 并在返回的图片文件响应头加上 <code>Access-Control-Allow-Origin: *</code> 即可解决。</p>',51)]))}const g=a(i,[["render",c]]);export{m as __pageData,g as default};
